CREATE TABLE public.api_keys (
    id integer NOT NULL,
    name character varying(64) NOT NULL,
    key_hash character varying(64) NOT NULL,
    key_prefix character varying(12) NOT NULL,
    plan character varying(16) DEFAULT 'free'::character varying NOT NULL,
    monthly_quota integer DEFAULT 500 NOT NULL,
    credits_balance bigint DEFAULT 0 NOT NULL,
    rate_limit_per_min integer DEFAULT 10 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp(0) with time zone NOT NULL,
    revoked_at timestamp(0) with time zone DEFAULT NULL::timestamp with time zone,
    stripe_customer_id character varying(64) DEFAULT NULL::character varying,
    stripe_subscription_id character varying(64) DEFAULT NULL::character varying,
    user_id integer NOT NULL
);
ALTER TABLE public.api_keys ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.api_keys_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.api_usage (
