CREATE TABLE public.builds (
    id integer NOT NULL,
    name character varying(80) NOT NULL,
    champion_id character varying(64) NOT NULL,
    game_version character varying(24) NOT NULL,
    description text,
    runes jsonb NOT NULL,
    steps jsonb NOT NULL,
    is_public boolean DEFAULT false NOT NULL,
    share_token character varying(24) NOT NULL,
    created_at timestamp(0) without time zone NOT NULL,
    updated_at timestamp(0) without time zone NOT NULL,
    owner_id integer NOT NULL,
    game_mode character varying(16) DEFAULT 'sr'::character varying NOT NULL,
    language character varying(8) DEFAULT 'en_US'::character varying NOT NULL
