CREATE TABLE public.contact_messages (
    id integer NOT NULL,
    category character varying(255) NOT NULL,
    name character varying(120) DEFAULT NULL::character varying,
    email character varying(255) NOT NULL,
    subject character varying(160) DEFAULT NULL::character varying,
    message text NOT NULL,
    locale character varying(16) DEFAULT NULL::character varying,
    ip character varying(64) DEFAULT NULL::character varying,
    status character varying(255) DEFAULT 'new'::character varying NOT NULL,
    created_at timestamp(0) without time zone NOT NULL,
    handled_at timestamp(0) without time zone DEFAULT NULL::timestamp without time zone,
    user_id integer
);
ALTER TABLE public.contact_messages ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.contact_messages_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
CREATE TABLE public.doctrine_migration_versions (
