    is_public_profile boolean DEFAULT false NOT NULL,
    favorite_champion_id character varying(64) DEFAULT NULL::character varying,
    favorite_item_id character varying(16) DEFAULT NULL::character varying,
    favorite_rune_id character varying(16) DEFAULT NULL::character varying,
    favorite_summoner_id character varying(64) DEFAULT NULL::character varying,
    created_at timestamp(0) without time zone NOT NULL,
    google_id character varying(30) DEFAULT NULL::character varying,
    riot_tagline character varying(5) DEFAULT NULL::character varying,
    is_supporter boolean DEFAULT false NOT NULL,
    is_banned boolean DEFAULT false NOT NULL,
    banned_at timestamp(0) with time zone DEFAULT NULL::timestamp with time zone,
    ban_reason character varying(255) DEFAULT NULL::character varying,
    is_verified boolean DEFAULT false NOT NULL,
    favorite_skin_id character varying(64) DEFAULT NULL::character varying,
    preferred_version character varying(24) DEFAULT NULL::character varying
